parameters.jsCode:
const body = $('Receive Guest Message').first().json.body || {};
const question = String(body.message || '').slice(0, 2000).trim();
const sessionId = String(body.sessionId || 'unknown').slice(0, 100);
const history = Array.isArray(body.history) ? body.history.slice(-8) : [];
const rows = $input.all().map(i => i.json).filter(r => r && typeof r.content === 'string' && r.content.trim());
rows.sort((a, b) => (a.chunk_index || 0) - (b.chunk_index || 0));

const STOP = new Set('a an the and or of to in on for with at by is are was were be do does did i you we they it this that what which who how when where can could would should may might my your our me us there their any have has had about from as please tell know want need'.split(' '));
const tokenize = s => String(s).toLowerCase().replace(/[^a-z0-9$€£ ]+/g, ' ').split(/\s+/).filter(w => w.length > 1 && !STOP.has(w));

const totalChars = rows.reduce((n, r) => n + r.content.length, 0);
let selected = rows;
if (totalChars > 48000) {
  const lastUser = history.filter(h => h.role === 'user').slice(-2).map(h => h.content).join(' ');
  const qTerms = tokenize(question + ' ' + lastUser);
  const docs = rows.map(r => tokenize(r.content));
  const N = docs.length;
  const avg = docs.reduce((n, d) => n + d.length, 0) / Math.max(N, 1);
  const df = {};
  for (const d of docs) for (const t of new Set(d)) df[t] = (df[t] || 0) + 1;
  const scored = rows.map((r, i) => {
    const d = docs[i];
    const tf = {};
    for (const t of d) tf[t] = (tf[t] || 0) + 1;
    let score = 0;
    for (const t of qTerms) {
      if (!tf[t]) continue;
      const idf = Math.log(1 + (N - df[t] + 0.5) / (df[t] + 0.5));
      score += idf * (tf[t] * 2.2) / (tf[t] + 1.2 * (0.25 + 0.75 * d.length / avg));
    }
    return { r, score };
  });
  selected = scored.sort((a, b) => b.score - a.score).slice(0, 12).map(s => s.r).sort((a, b) => a.chunk_index - b.chunk_index);
}

const context = selected.map(r => '[Section ' + (r.chunk_index + 1) + ']\n' + r.content).join('\n\n---\n\n');
const historyText = history.map(h => (h.role === 'user' ? 'Guest' : 'Assistant') + ': ' + String(h.content || '').slice(0, 1500)).join('\n');
return [{ json: {
  sessionId,
  question,
  hasKnowledge: rows.length > 0,
  context: rows.length ? context : '(No hotel information document has been uploaded yet.)',
  historyText: historyText || '(This is the first message of the conversation.)'
}}];

