parameters.jsCode:
const ctx = $('Retrieve Relevant Context').first().json;
const raw = $input.first().json.output || {};
const CATS = ['Rooms & Suites','Pricing & Rates','Dining & Restaurant','Facilities & Amenities','Spa & Wellness','Check-in & Policies','Location & Transport','Events & Meetings','Guest Services','General'];
const FALLBACK = "I'm sorry, I don't have that information right now. Would you like to leave your contact details so a member of our team can get back to you?";
let answered = raw.answered === true;
let answer = String(raw.answer || '').trim();
if (!ctx.hasKnowledge) answered = false;
if (!answer || !answered) { answer = answered ? answer : FALLBACK; }
if (/i'?m sorry, i don'?t have that information/i.test(answer)) answered = false;
const category = CATS.includes(raw.category) ? raw.category : 'General';
return [{ json: {
  session_id: ctx.sessionId,
  question: ctx.question,
  answer,
  answered,
  category,
  asked_at: new Date().toISOString()
}}];
